def seed_catalogue(apps, schema_editor):
    categories = apps.get_model("postup", "CompetitionCategory").objects.using(schema_editor.connection.alias)
    competitions = apps.get_model("postup", "Competition").objects.using(schema_editor.connection.alias)
    initial = [
        ("informatics", "Олімпіада з інформатики", [("informatics", "Олімпіада з інформатики")]),
        ("man", "МАН", [("man", "МАН")]),
        ("ai", "Олімпіада зі штучного інтелекту", [("ai", "Олімпіада зі штучного інтелекту")]),
        ("junior-girls", "Юніорська та дівоча олімпіади",
         [("junior", "Юніорська олімпіада"), ("girls", "Дівоча олімпіада")]),
        ("icpc", "ICPC", [("icpc", "ICPC")]),
        ("genius", "Олімпіада геніїв", [("genius", "Олімпіада геніїв")]),
    ]
    for slug, name, entries in initial:
        category, _ = categories.get_or_create(slug=slug, defaults={"name": name})
        for code, title in entries:
            competitions.get_or_create(slug=code, defaults={
                "name": title, "category": category, "asks_topic": code == "man", "team_by_default": code == "icpc",
            })


